from lib import *
S = SS('h41')
steps = [
    step("客户端 → A → B:B 返回各种错误码,A 原样往外传 vs 按我的策略翻译(NotFound、AlreadyExists、ResourceExhausted、Unavailable、Canceled 保持原样;DeadlineExceeded 改成 Unavailable;其余全部改成 Internal)。A 原样透传时,客户端看到的 code 和 B 返回的完全一样:B 返回 InvalidArgument、Unauthenticated、PermissionDenied、FailedPrecondition,客户端也看到这些——可是这些很可能不是客户端的错:A 传给 B 的参数是 A 自己拼的,A 调 B 用的凭证也是 A 自己的。翻译之后这四个都变成 Internal,NotFound、ResourceExhausted、Unavailable、Internal 不变,DeadlineExceeded 变成 Unavailable。这个翻译表是我的示例做法,不是 gRPC 强制的规则;核心是“code 的含义是对着当前调用者说的”。", t=tl(S(1)), done=lidx(S(1), '  Internal             Internal             Internal'), mark=lidx(S(1), 'InvalidArgument      InvalidArgument'), b=bars([['测试的 B 错误码个数', 9, '9'], ['翻译后 code 改变的个数', 5, '5']], 10, mark=[1], done=[0]), kv=KV([['InvalidArgument / Unauthenticated / PermissionDenied / FailedPrecondition', '透传:客户端以为是自己的错;翻译后 Internal'], ['DeadlineExceeded', '翻译后 Unavailable(下游超时)'], ['NotFound / ResourceExhausted / Unavailable / Internal', '不变']], ['InvalidArgument / Unauthenticated / PermissionDenied / FailedPrecondition'])),
    step("错误信息会泄漏内部细节:B 的错误 message 里写着库表名和内网地址(“B 内部错误:库表 orders_v2 找不到,连接 10.0.0.5:5432 失败”)。A 透传时客户端原样看到这句话,code 也是 Internal;A 翻译后客户端只看到“下游服务出错”。B 整个停掉时,透传的客户端看到的 message 是“connection error: desc = \"transport: Error while dialing: dial tcp 127.0.0.1:…: connect: connection refused…”——带着 B 的地址;翻译后只有“下游服务:Unavailable”。对外的服务不应该把下游的 message 原样透出去(内部细节写日志就行)。", t=tl(S(2)), done=lidx(S(2), 'B 已经停掉,翻译'), mark=lidx(S(2), '透传:客户端看到'), b=bars([['透传:message 里含内网地址(1=含)', 1, '含'], ['翻译:message 里含内网地址', 0, '不含']], 1.2, mark=[0], done=[1]), kv=KV([['透传', '客户端看到库表名、内网 IP、拨号地址'], ['翻译', '只有“下游服务出错”'], ['原则', '细节写日志,不返回给调用者']], ['原则'])),
    step("重试放大:B 一直返回 Unavailable。只有客户端重试(最多 3 次 UNAVAILABLE):一次客户端调用让 B 收到 3 次;客户端有 3 次、A 应用层也重试 3 次:B 收到 9 次;客户端有 3 次、A 用 gRPC 的重试策略也配 3 次:同样 B 收到 9 次;只有 A 重试 3 次(客户端不重试):B 收到 3 次。每多一层重试,倍数就乘上去——三层就是 27 倍(我没有实测三层,这是外推)。所以多层服务里重试通常只放在一层(靠近用户的边缘,或最靠近失败的那一层),并配合重试节流(第 19 篇)。", t=tl(S(3)), done=lidx(S(3), '只有 A 重试'), mark=lidx(S(3), '只有客户端重试'), b=bars([['只有客户端重试:B 收到', 3, '3'], ['客户端 × A(应用层):B 收到', 9, '9'], ['客户端 × A(gRPC 策略):B 收到', 9, '9'], ['只有 A 重试:B 收到', 3, '3']], 10, mark=[1, 2], done=[0, 3]), kv=KV([['一层重试 3 次', 'B 收到 3 次'], ['两层各 3 次', 'B 收到 9 次(3 × 3)'], ['建议', '只在一层重试 + 重试节流']], ['建议'])),
    step("下游超时该翻译成什么:A 调 B 带 300 ms 超时(B 要 1 秒),客户端有 2 秒 deadline 和“UNAVAILABLE 重试 3 次”的策略。A 把 B 的超时透传(DeadlineExceeded):客户端最终 DeadlineExceeded,用了 303.7 ms,B 收到 1 次——客户端明明还有 1.7 秒预算,拿到的却是“超时”,而且 DeadlineExceeded 不在重试范围内;A 翻译成 Unavailable:客户端按策略重试,最终 Unavailable,用了 937.6 ms,B 收到 3 次(到达时刻约 1.9 ms、314.6 ms、635.5 ms)——每次尝试 300 ms,三次下来正好把慢下游又打了 3 次。翻译成什么没有标准答案:翻译成 Unavailable 让客户端有机会重试,也让一个慢下游被重试放大;要看你的重试和过载策略(第 18、19 篇)。", t=tl(S(4)), done=lidx(S(4), '翻译(Unavailable)'), mark=lidx(S(4), '透传(DeadlineExceeded)'), b=bars([['透传:客户端用时 ms', 303.7, '303.7'], ['翻译成 Unavailable:客户端用时 ms', 937.6, '937.6'], ['透传:B 收到次数', 1, '1'], ['翻译:B 收到次数', 3, '3']], 1000, mark=[1, 3], done=[0, 2]), kv=KV([['透传 DeadlineExceeded', '303.7 ms,B 收到 1 次,客户端不重试'], ['翻译 Unavailable', '937.6 ms,B 收到 3 次(重试)'], ['取舍', '给客户端重试机会 vs 放大慢下游的压力']], ['取舍'])),
]
A = mkarth('h41', 41, 'gRPC,错误传播,状态码翻译,重试放大,信息泄漏,微服务,Go,真实验证,动画演示',
    '实测服务 A 调服务 B 时的错误传播:原样透传会把 B 的 InvalidArgument、Unauthenticated 等错误当成客户端的错;message 会泄漏库表名和内网地址;两层各重试 3 次 B 收到 9 次;下游超时翻译成 Unavailable 还是 DeadlineExceeded 会改变重试行为。',
    '服务 A 调服务 B 失败了,A 该把错误怎么交给自己的客户端?直接 return err 有什么问题?重试叠加会怎样?下游超时该报什么码?这篇用 客户端 → A → B 把每种做法的后果都量出来。',
    [('透传 4 个 code', 'B 的 InvalidArgument、Unauthenticated、PermissionDenied、FailedPrecondition 被透传给客户端,客户端会误以为是自己的错'), ('3 → 9', '客户端 3 次重试 × A 的 3 次重试,B 收到的次数'), ('303.7 ms vs 937.6 ms', 'A 把下游超时透传成 DeadlineExceeded 与翻译成 Unavailable 时,客户端的总耗时')],
    [('code 的含义是对着调用者的', '<p>下游返回 InvalidArgument,说的是 A 传的参数有问题,不是 A 的客户端的参数有问题。原样透传会让客户端误解、误处理。常见做法是把它们折叠成 Internal。翻译表要自己定,不是协议规定的。</p>'),
     ('message 不要透传', '<p>下游的 message 里可能有表名、地址等内部信息,对外返回通用描述,细节写日志。</p>'),
     ('重试要放在一层', '<p>每层都重试,下游收到的次数是各层次数相乘。多层服务里通常只在一层重试,并配合重试节流。</p>'),
     ('超时的翻译', '<p>下游超时可以报 DeadlineExceeded 或 Unavailable,两者对客户端重试行为的影响不同:翻译成 Unavailable 会触发客户端重试,可能把慢下游进一步压垮。</p>')],
    steps,
    [ENV_H + '。链路是本机进程内的 客户端 → A → B;B 按请求里的 N 返回对应的 gRPC code;A 的翻译函数是我写的示例策略;总耗时在调用返回后立即读取(调用之后不再 sleep);B 收到的次数由 B handler 里的计数器得到',
     '没有验证:三层及以上重试的放大倍数(27 倍是外推);翻译成 Unavailable 之外的方案(如自定义 Aborted 或用 errdetails 标明来源);重试预算(retry budget)或 hedging;翻译对 grpc-gateway 的 HTTP 状态码的影响(第 29 篇);跨语言服务的状态码约定;status 的 details 在翻译时是否保留(第 22 篇)'],
    '错误翻译')
